package setup

import (
	"encoding/json"
	"strings"
)

const piManagedPrefix = "// kapi managed pi extension: " + Marker

func piExtension(command string) string {
	q, err := json.Marshal(command)
	if err != nil {
		panic(err)
	}
	return strings.ReplaceAll(piExtensionTemplate, "__COMMAND__", string(q))
}

const piExtensionTemplate = `// kapi managed pi extension: kapi
// Generated by kapi setup. Safe to edit only if you remove the marker above.
import { execFile } from "node:child_process";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

const command = __COMMAND__;

function idleInstruction(cwd: string): Promise<string> {
  return new Promise((resolve) => {
    execFile(command, ["hook-idle", cwd], { cwd, timeout: 3000 }, (error, stdout) => {
      resolve(error ? "" : stdout.trim());
    });
  });
}

export default function (pi: ExtensionAPI) {
  pi.on("agent_before_settle", async (event, ctx) => {
    if (!event.canContinue || event.outcome !== "completed") return;
    const content = await idleInstruction(ctx.cwd);
    if (!content) return;
    return {
      entries: [{ type: "custom_message", customType: "kapi-idle", content, display: false }],
      continue: true,
    };
  });
}
`
